insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g4_science_v1'
from (values
('112.6.b.6.A',2,'A student drops a small metal bolt, a cork, and a marble into water. The cork floats and the others sink. What property did the student test?','["relative density", "texture", "temperature", "magnetism"]'::jsonb,0,'Relative density is the ability to sink or float in water.','original'),
('112.6.b.6.A',3,'Which tool measures the mass of a small object?','["a graduated cylinder", "a balance", "a thermometer", "a hand lens"]'::jsonb,1,'A balance measures mass.','original'),
('112.6.b.6.A',3,'A student groups objects as ''attracted to a magnet'' and ''not attracted to a magnet.'' Which property is used?','["state of matter", "temperature", "magnetism", "density"]'::jsonb,2,'The property being sorted is how the objects respond to a magnet.','original'),
('112.6.b.6.A',3,'Which sample is a gas at room temperature?','["salt", "juice", "iron", "oxygen"]'::jsonb,3,'Oxygen is a gas at room temperature.','original'),
('112.6.b.6.A',3,'A student measures the temperature of three cups of water: 15°C, 40°C, and 25°C. Which is the warmest?','["the 40°C cup", "the 15°C cup", "the 25°C cup", "all are the same"]'::jsonb,0,'A higher temperature means warmer.','original'),
('112.6.b.6.A',4,'A block floats in water but sinks in vegetable oil. What can the student conclude?','["the block is denser than the water", "the block is denser than the oil but less dense than the water", "the block has no mass", "the block is less dense than the oil"]'::jsonb,1,'It floats in water, so it is less dense than water. It sinks in oil, so it is denser than the oil.','original'),
('112.6.b.6.A',3,'Which list is in order from SOLID, to LIQUID, to GAS?','["steam, water, a rock", "a rock, steam, water", "a rock, water, steam", "water, a rock, steam"]'::jsonb,2,'A rock is a solid, water is a liquid, and steam is a gas.','original'),
('112.6.b.6.B',2,'Sugar is stirred into water and seems to disappear. What is the mixture called?','["an element", "a solid", "a gas", "a solution"]'::jsonb,3,'A solution is a mixture where one substance spreads evenly through another.','original'),
('112.6.b.6.B',3,'Which is a mixture where you can still see the separate parts?','["a bowl of trail mix", "a glass of clear tea", "sugar in water", "salt in water"]'::jsonb,0,'In trail mix, each part is still visible.','original'),
('112.6.b.6.B',3,'Which is a solution of a solid in a liquid?','["pebbles in a jar", "salt dissolved in water", "sand in water", "oil on water"]'::jsonb,1,'Salt dissolves and is spread evenly in water.','original'),
('112.6.b.6.B',3,'Oil and water are poured into a jar and shaken. What happens after a while?','["they become a solid", "they turn into one liquid", "they separate into layers", "they disappear"]'::jsonb,2,'Oil and water do not dissolve in each other.','original'),
('112.6.b.6.B',3,'A student stirs soil into water. What is this mixture?','["an element", "a solution of two gases", "a single substance", "a mixture of a solid in a liquid"]'::jsonb,3,'Soil and water mix, but the soil can settle out.','original'),
('112.6.b.6.B',4,'Which can be separated by pouring through a filter?','["sand mixed in water", "juice mixed with water", "salt dissolved in water", "sugar dissolved in water"]'::jsonb,0,'Sand pieces are large enough to stay in the filter.','original'),
('112.6.b.6.B',3,'Lemonade is made by stirring lemon juice and sugar into water. Why is it a solution?','["the parts burn", "the parts are mixed evenly", "the parts are all solids", "the parts stay in layers"]'::jsonb,1,'A solution is evenly mixed.','original'),
('112.6.b.6.C',3,'A student mixes 100 g of soil with 200 g of water. What is the total mass of the mixture?','["250 g", "100 g", "300 g", "200 g"]'::jsonb,2,'Mass is conserved, so 100 g plus 200 g equals 300 g.','original'),
('112.6.b.6.C',3,'A student pours 50 g of salt into 150 g of water and stirs. What is the mass of the salt water?','["150 g", "50 g", "100 g", "200 g"]'::jsonb,3,'Matter is conserved when a solution forms, so the masses add.','original'),
('112.6.b.6.C',3,'A student weighs sugar and water separately: 40 g and 160 g. After stirring, what will the mixture''s mass be?','["200 g", "40 g", "120 g", "160 g"]'::jsonb,0,'40 g plus 160 g equals 200 g.','original'),
('112.6.b.6.C',3,'A sugar cube dissolves in water and disappears. What happened to the sugar?','["it was destroyed", "it is still there, spread through the water", "it turned into water", "it became a gas only"]'::jsonb,1,'Matter is not destroyed when it dissolves.','original'),
('112.6.b.6.C',4,'A student mixes oil and water in a jar with a lid. The total mass before and after shaking stays the same. What does this show?','["matter was created", "matter was destroyed", "matter is conserved", "mass doesn''t matter"]'::jsonb,2,'The mass stayed the same.','original'),
('112.6.b.6.C',3,'100 g of sand and 100 g of water are mixed. How much mass does the mixture have?','["150 g", "100 g", "50 g", "200 g"]'::jsonb,3,'Mass is conserved in a mixture.','original'),
('112.6.b.6.C',4,'A cup with soil weighs 80 g. The student adds 120 g of water. What is the combined mass of the cup, soil, and water, if the empty cup weighs 20 g and the soil is 60 g?','["200 g", "220 g", "180 g", "140 g"]'::jsonb,0,'20 g + 60 g + 120 g = 200 g.','original'),
('112.6.b.7',2,'What force pulls a falling apple toward the ground?','["magnetism", "gravity", "wind", "friction"]'::jsonb,1,'Gravity pulls objects toward Earth.','original'),
('112.6.b.7',3,'A block slides slower on carpet than on smooth tile. What force is greater on the carpet?','["light", "gravity", "friction", "magnetism"]'::jsonb,2,'Rough surfaces create more friction.','original'),
('112.6.b.7',3,'A student rubs hands together and they get warm. What force causes the warmth?','["wind", "gravity", "magnetism", "friction"]'::jsonb,3,'Friction between surfaces makes heat.','original'),
('112.6.b.7',3,'A magnet pulls on a steel nail across a small gap. What does this show?','["magnetic force can act without touching", "gravity can act only by touching", "friction stops the nail", "magnets only push"]'::jsonb,0,'Magnetic force acts at a distance.','original'),
('112.6.b.7',3,'A student rolls a ball on grass and on a wood floor. On which does the ball slow down faster?','["neither one", "the grass", "they are the same", "the wood floor"]'::jsonb,1,'Grass has more friction than wood.','original'),
('112.6.b.7',3,'Which force keeps a skydiver falling toward Earth?','["magnetism", "friction only", "gravity", "light"]'::jsonb,2,'Gravity pulls the skydiver down.','original'),
('112.6.b.7',4,'A student rolls a toy car on three surfaces. Trial 1: 20 cm. Trial 2: 50 cm. Trial 3: 120 cm. Which surface has the least friction?','["they are the same", "the surface in Trial 2", "the surface in Trial 1", "the surface in Trial 3"]'::jsonb,3,'The car travels farthest on the surface with the least friction.','original'),
('112.6.b.8.A',2,'A moving bowling ball hits pins. What happens to the pins?','["they get energy and move", "they turn to light", "they stay still", "they melt"]'::jsonb,0,'Energy is transferred from the ball to the pins.','original'),
('112.6.b.8.A',3,'A pebble is dropped in a pond. What do you see?','["the pond freezing", "waves moving outward", "the water turning colors", "the pond going dry"]'::jsonb,1,'The pebble''s energy makes water waves.','original'),
('112.6.b.8.A',3,'A drum is hit and a bell beside it begins to vibrate. What is traveling from the drum to the bell?','["nothing", "light energy", "sound energy", "heat only"]'::jsonb,2,'Sound waves carry energy.','original'),
('112.6.b.8.A',3,'A moving billiard ball hits a still ball and the still ball starts moving. What happened?','["the balls changed color", "gravity stopped", "energy was destroyed", "energy was transferred"]'::jsonb,3,'The moving ball passed energy to the still one.','original'),
('112.6.b.8.A',3,'Waves in the ocean can move a boat up and down. What does this show?','["water waves carry energy", "the boat creates energy", "boats make waves only", "waves carry matter far away"]'::jsonb,0,'Waves transfer energy.','original'),
('112.6.b.8.A',3,'Which shows energy transfer by sound?','["ice melting", "a window rattling from a loud boom", "a shadow on the wall", "a plant growing"]'::jsonb,1,'A loud sound can make objects vibrate.','original'),
('112.6.b.8.A',4,'A student drops a rock into a bucket and sees ripples spread across the water. What causes the ripples?','["gravity pushing sideways", "energy from the water entering the rock", "energy from the rock moving into the water", "the bucket creating energy"]'::jsonb,2,'The rock''s energy transfers to the water as waves.','original'),
('112.6.b.8.B',2,'Which material is a good conductor of electricity?','["plastic", "wood", "rubber", "copper"]'::jsonb,3,'Metals like copper conduct electricity.','original'),
('112.6.b.8.B',2,'Which material is a good insulator?','["rubber", "aluminum foil", "copper", "iron"]'::jsonb,0,'Rubber does not let electricity pass easily.','original'),
('112.6.b.8.B',3,'Why is the handle of a pot made of plastic or wood?','["they are magnetic", "they do not conduct heat well", "they melt easily", "they conduct heat well"]'::jsonb,1,'Insulators keep the handle cooler.','original'),
('112.6.b.8.B',3,'Why are electrical wires coated with plastic?','["to make the wire heavier", "to make the wire shine", "to keep electricity from reaching people", "to make the wire a magnet"]'::jsonb,2,'Plastic insulates and protects people.','original'),
('112.6.b.8.B',3,'A metal spoon left in hot soup gets hot quickly. What does this show?','["spoons make heat", "soup cannot heat metal", "metal insulates heat", "metal conducts heat well"]'::jsonb,3,'Metals conduct thermal energy.','original'),
('112.6.b.8.B',3,'Which is a good thermal insulator?','["foam", "silver", "copper", "aluminum"]'::jsonb,0,'Foam resists the flow of heat.','original'),
('112.6.b.8.B',4,'A student tests a bulb circuit with a coin, a pencil eraser, and a metal key. The bulb lights with the coin and the key but not the eraser. What does the eraser do?','["it makes light", "it insulates", "it conducts", "it makes heat"]'::jsonb,1,'The eraser blocks the flow of electricity.','original'),
('112.6.b.8.C',2,'What is a closed circuit?','["a path with no battery", "a path that stops at a gap", "a complete path for electricity", "a broken path"]'::jsonb,2,'A closed circuit has no gaps.','original'),
