('112.6.b.9.A',3,'A data table shows average highs: Jan 55°F, Apr 75°F, Jul 95°F, Oct 78°F. Which month is probably the hottest?','["July", "January", "April", "October"]'::jsonb,0,'95°F is the highest.','original'),
('112.6.b.9.A',3,'Temperatures are 80°F, 70°F, 60°F, 50°F in four months in order. Which season change is likely?','["spring turning to summer", "summer turning to winter", "no change", "winter turning to summer"]'::jsonb,1,'Cooling temps show a change toward winter.','original'),
('112.6.b.9.A',3,'In which season is daylight SHORTEST?','["fall", "summer", "winter", "spring"]'::jsonb,2,'Winter has the shortest days.','original'),
